      const blocked = [...(slotsByShowAll.get(slug) || [])]
        .filter((s) => !unblockedKeys.has(slotKey(s)))
        .sort(byEnd);
      slots = [...unblocked, ...blocked];
    }
    for (const slot of slots) {
      const sameDay = perDay.get(slot.date) || [];
      if (sameDay.every((c) => compatible(c, slot, gapOpts))) {
