        break;
      }
    }
  }

  // --- Pass 2: greedy earliest-finish for everything else ------------------
  const candidates = [];
  for (const [slug, slots] of slotsByShow) {
    if (forcedSlugs.has(slug)) continue; // handled in pass 1
    for (const slot of slots) candidates.push(slot);
